#!/usr/bin/env bash
# ZONO BILLING 8.2 — 7-day grace → BILLING_RESTRICTED + canonical entitlement gate.
# macOS-safe base64 decode. No DB migration (uses existing grace_until column).
set -euo pipefail
cd "$(dirname "$0")"
echo "→ repo: $(pwd)"
git am --abort 2>/dev/null || true
git fetch origin
git checkout main
git reset --hard origin/main
cat > /tmp/zono-billing82.patch.b64 <<'B64EOF'

B64EOF
base64 -d < /tmp/zono-billing82.patch.b64 > /tmp/zono-billing82.patch
git am --3way /tmp/zono-billing82.patch
echo "→ commit applied:"; git log --oneline -2
git push origin main
echo "✓ pushed. Redeploy picks up the grace lifecycle + entitlement gate."
